SELECT count(*) AS n FROM (
    SELECT DISTINCT customer_id
    FROM orders
    WHERE created_at >= TIMESTAMP '2026-02-18'
      AND customer_id IS NOT NULL
) AS sub;

SELECT *
FROM emp e1
WHERE e1.empno > (SELECT MIN(deptno) FROM dept);

SELECT empno,
       CASE WHEN mgr IS NULL THEN 0 ELSE 1 END AS count
FROM emp;

SELECT d.name,
       d.deptno > (SELECT min(deptno) FROM emp) AS deptno_gt_any_emp
FROM dept AS d;

SELECT d.deptno,
       CASE WHEN d.name IS NULL THEN 0 ELSE 1 END AS count_distinct_name
FROM dept d;
